    NodeKind kind;

    union {
        VarDecl var_decl;
        Expr *expr;        /* for STMT_EXPR */
        ReturnStmt ret;
        IfStmt if_stmt;
        WhileStmt while_stmt;
        ForStmt for_stmt;
        BlockStmt block;
        StructDef struct_def;
    };
} Stmt;

/* ---- Functions ---- */

typedef struct {
    const char *name;
    const char **param_names;
    FlType **param_types;
    int param_count;
    FlType *return_type;
    Stmt *body;
    int is_extern;
} FuncDef;

